const input = $json || {};

const sampleApprovalOutput = {
  success: true,
  result: {
    summary: {
      inputActionCount: 4,
      evaluatedActionCount: 4,
      pendingApprovalCount: 1,
      autoApprovedCount: 2,
      blockedCount: 1,
      rejectedCount: 0
    },
    pendingApprovals: [
      {
        approvalId: 'apr_sample_123',
        actionId: 'social-1-calendar-2',
        recommendationId: 'social-1',
        type: 'calendar_create',
        status: 'pending_approval',
        riskLevel: 'medium',
        summary: 'Add International Social Mixer to calendar',
        description: 'Prepare a Google Calendar event for user approval.',
        payload: {
          title: 'International Social Mixer',
          start: '2026-08-01T20:00:00+04:00',
          end: '2026-08-01T23:00:00+04:00',
          location: 'Dubai Marina'
        },
        channel: 'telegram',
        createdAt: new Date().toISOString(),
        expiresAt: new Date(Date.now() + 86400000).toISOString(),
        allowedResponses: ['approve', 'reject', 'alternative']
      }
    ],
    autoApprovedActions: [
      {
        actionId: 'social-1-show-1',
        recommendationId: 'social-1',
        recommendationTitle: 'International Social Mixer',
        type: 'show_recommendation',
        title: 'Show recommendation: International Social Mixer',
        description: 'Strong social fit and easy to attend alone.',
        payload: {
          recommendation: {
            title: 'International Social Mixer',
            score: 88,
            classification: 'Must Go',
            reason: 'Strong social fit and easy to attend alone.',
            location: 'Dubai Marina',
            start: '2026-08-01T20:00:00+04:00',
            estimatedCost: 120,
            currency: 'AED'
          }
        },
        channel: 'chatgpt',
        priority: 'high',
        status: 'approved'
      },
      {
        actionId: 'social-1-reminder-3',
        recommendationId: 'social-1',
        recommendationTitle: 'International Social Mixer',
        type: 'personal_reminder',
        title: 'Reminder for International Social Mixer',
        description: 'Prepare a personal reminder.',
        payload: {
          eventTitle: 'International Social Mixer',
          eventStart: '2026-08-01T20:00:00+04:00',
          reminderMinutesBefore: 60
        },
        channel: 'telegram',
        scheduledFor: '2026-08-01T20:00:00+04:00',
        status: 'approved'
      }
    ],
    blockedActions: [
      {
        actionId: 'travel-1-purchase-4',
        type: 'purchase_execute',
        title: 'Purchase trip booking',
        status: 'blocked',
        reason: 'Execution of purchases is not supported.'
      }
    ]
  }
};

return [{
  json: {
    request: input.request || {
      text: 'Bu akşam ne yapayım?',
      channel: 'manual_test',
      userId: 'savas',
      conversationId: 'manual-test'
    },
    context: input.context || {
      timezone: 'Asia/Dubai',
      userContext: {
        identity: {
          name: 'Savaş',
          language: 'Turkish'
        }
      }
    },
    approvalEngineOutput:
      input.approvalEngineOutput ||
      (
        input.result?.pendingApprovals || input.result?.autoApprovedActions
          ? input
          : sampleApprovalOutput
      ),
    metadata: input.metadata || {
      correlationId: `notification-${Date.now()}`,
      testMode: true
    }
  }
}];

const input = $json || {};
const approvalOutput = input.approvalEngineOutput || {};
const result = approvalOutput.result || {};
const request = input.request || {};
const context = input.context || {};
const metadata = input.metadata || {};

const pendingApprovals = Array.isArray(result.pendingApprovals)
  ? result.pendingApprovals
  : [];

const autoApprovedActions = Array.isArray(result.autoApprovedActions)
  ? result.autoApprovedActions
  : [];

const blockedActions = Array.isArray(result.blockedActions)
  ? result.blockedActions
  : [];

const userName =
  context.userContext?.identity?.name ||
  context.identity?.name ||
  'Savaş';

const language =
  context.userContext?.identity?.language ||
  context.identity?.language ||
  'Turkish';

const notifications = [];
const logs = [];

const formatDateTime = value => {
  if (!value) return null;
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return value;

  return new Intl.DateTimeFormat('en-GB', {
    timeZone: 'Asia/Dubai',
    dateStyle: 'medium',
    timeStyle: 'short'
  }).format(date);
};

const chooseChannel = preferred => {
  if (preferred === 'telegram') return 'telegram';
  if (preferred === 'whatsapp') return 'whatsapp';
  if (preferred === 'chatgpt') return 'chatgpt';
  return request.channel || 'chatgpt';
};

const addNotification = ({
  channel,
  type,
  title,
  message,
  buttons = [],
  scheduledFor = null,
  priority = 'normal',
  relatedActionId = null,
  approvalId = null,
  metadata: extraMetadata = {}
}) => {
  notifications.push({
    notificationId:
      `ntf_${Date.now()}_${notifications.length + 1}`,
    channel,
    type,
    title,
    message,
    buttons,
    scheduledFor,
    priority,
    relatedActionId,
    approvalId,
    status: 'prepared',
    createdAt: new Date().toISOString(),
    metadata: extraMetadata
  });
};

// 1. Approval notifications
for (const approval of pendingApprovals) {
  const payload = approval.payload || {};
  const eventStart = formatDateTime(payload.start);
  const eventEnd = formatDateTime(payload.end);

  const detailLines = [
    approval.description || '',
    payload.location ? `Location: ${payload.location}` : '',
    eventStart ? `Start: ${eventStart}` : '',
    eventEnd ? `End: ${eventEnd}` : '',
    `Risk: ${approval.riskLevel || 'medium'}`
  ].filter(Boolean);

  addNotification({
    channel: chooseChannel(approval.channel || 'telegram'),
    type: 'approval_request',
    title: approval.summary || 'Approval required',
    message:
      `${approval.summary || 'Approval required'}\n\n` +
      `${detailLines.join('\n')}\n\n` +
      `Proceed with this action?`,
    buttons: [
      {
        label: 'Approve',
        value: `approve:${approval.actionId}`
      },
      {
        label: 'Reject',
        value: `reject:${approval.actionId}`
      },
      {
        label: 'Alternative',
        value: `alternative:${approval.actionId}`
      }
    ],
    priority:
      approval.riskLevel === 'high'
        ? 'high'
        : 'normal',
    relatedActionId: approval.actionId,
    approvalId: approval.approvalId,
    metadata: {
      expiresAt: approval.expiresAt,
      allowedResponses: approval.allowedResponses || []
    }
  });
}

// 2. Auto-approved actions
for (const action of autoApprovedActions) {
  const type = String(action.type || '');
  const preferredChannel = chooseChannel(action.channel);

  if (type === 'show_recommendation') {
    const recommendation =
      action.payload?.recommendation || {};

    const parts = [
      recommendation.title || action.recommendationTitle || action.title,
      recommendation.classification
        ? `${recommendation.classification} · ${recommendation.score ?? ''}/100`
        : '',
      recommendation.reason || action.description || '',
      recommendation.location
        ? `Location: ${recommendation.location}`
        : '',
      recommendation.start
        ? `Time: ${formatDateTime(recommendation.start)}`
        : '',
      recommendation.estimatedCost !== null &&
      recommendation.estimatedCost !== undefined
        ? `Estimated cost: ${recommendation.estimatedCost} ${recommendation.currency || 'AED'}`
        : ''
    ].filter(Boolean);

    addNotification({
      channel: preferredChannel,
      type: 'recommendation',
      title:
        recommendation.title ||
        action.recommendationTitle ||
        'Recommendation',
      message: parts.join('\n'),
      priority: action.priority || 'normal',
      relatedActionId: action.actionId
    });
  }

  if (type === 'personal_reminder') {
    const eventTitle =
      action.payload?.eventTitle ||
      action.recommendationTitle ||
      action.title;

    addNotification({
      channel: preferredChannel || 'telegram',
      type: 'reminder',
      title: eventTitle,
      message:
        `${userName}, ${eventTitle} is coming up. ` +
        `Prepare and leave enough travel time.`,
      scheduledFor: action.scheduledFor || null,
      priority: action.priority || 'normal',
      relatedActionId: action.actionId
    });
  }

  if (type === 'feedback_request') {
    addNotification({
      channel: preferredChannel || 'telegram',
      type: 'feedback_request',
      title:
        `How was ${action.recommendationTitle || 'the activity'}?`,
      message:
        `Did you attend? Rate it from 1 to 5, tell me whether you met someone new, and whether you would repeat it.`,
      buttons: [
        { label: 'Attended', value: `attended:${action.actionId}` },
        { label: 'Did not attend', value: `not_attended:${action.actionId}` }
      ],
      scheduledFor: action.scheduledFor || null,
      priority: 'normal',
      relatedActionId: action.actionId
    });
  }

  if (
    ['preparation_checklist', 'fitness_preparation', 'travel_plan'].includes(type)
  ) {
    addNotification({
      channel: preferredChannel || 'chatgpt',
      type: 'preparation',
      title: action.title,
      message:
        `${action.description || 'Preparation is ready.'}\n\n` +
        `Open ChatGPT Mobile for the detailed plan.`,
      priority: action.priority || 'normal',
      relatedActionId: action.actionId
    });
  }
}

// 3. Blocked action notifications
for (const action of blockedActions) {
  addNotification({
    channel: request.channel || 'chatgpt',
    type: 'blocked_action',
    title: action.title || 'Action blocked',
    message:
      `${action.reason || 'This action cannot be executed automatically.'}\n\n` +
      `I can still prepare options or instructions for you.`,
    priority: 'high',
    relatedActionId: action.actionId
  });
}

// 4. Channel payloads
const chatgptMessages = notifications
  .filter(item => item.channel === 'chatgpt')
  .map(item => ({
    notificationId: item.notificationId,
    title: item.title,
    message: item.message,
    type: item.type
  }));

const telegramMessages = notifications
  .filter(item => item.channel === 'telegram')
  .map(item => ({
    notificationId: item.notificationId,
    chatId:
      request.telegramChatId ||
      request.userId ||
      null,
    text: `*${item.title}*\n\n${item.message}`,
    parseMode: 'Markdown',
    buttons: item.buttons,
    scheduledFor: item.scheduledFor,
    type: item.type,
    approvalId: item.approvalId,
    relatedActionId: item.relatedActionId
  }));

const whatsappMessages = notifications
  .filter(item => item.channel === 'whatsapp')
  .map(item => ({
    notificationId: item.notificationId,
    to:
      request.whatsappNumber ||
      null,
    text:
      `${item.title}\n\n${item.message}`,
    scheduledFor: item.scheduledFor,
    type: item.type,
    relatedActionId: item.relatedActionId
  }));

const summary = {
  notificationCount: notifications.length,
  chatgptCount: chatgptMessages.length,
  telegramCount: telegramMessages.length,
  whatsappCount: whatsappMessages.length,
  approvalNotificationCount:
    notifications.filter(item => item.type === 'approval_request').length,
  reminderCount:
    notifications.filter(item => item.type === 'reminder').length,
  blockedNotificationCount:
    notifications.filter(item => item.type === 'blocked_action').length
};

let nextAction;

if (notifications.length === 0) {
  nextAction = {
    type: 'stop',
    targetWorkflow: null
  };
} else {
  nextAction = {
    type: 'dispatch_notifications',
    targetWorkflow: 'Concierge OS - Channel Dispatcher'
  };
}

return [{
  json: {
    success: true,
    result: {
      summary,
      notifications,
      channelPayloads: {
        chatgpt: chatgptMessages,
        telegram: telegramMessages,
        whatsapp: whatsappMessages
      }
    },
    memoryUpdates: notifications.map(item => ({
      type: 'notification_history',
      operation: 'append',
      payload: {
        notificationId: item.notificationId,
        channel: item.channel,
        type: item.type,
        title: item.title,
        status: item.status,
        createdAt: item.createdAt
      }
    })),
    approvalRequests: pendingApprovals,
    logs: [
      {
        timestamp: new Date().toISOString(),
        workflow: 'Concierge OS - Notification Engine',
        level: 'info',
        correlationId: metadata.correlationId || '',
        message:
          `Prepared ${notifications.length} notifications.`,
        details: summary
      },
      ...logs
    ],
    nextAction,
    error: null
  }
}];
